--write a procedure that takes prod_id and discounted price as input
-- and apply discounted price in all given prod ids
CREATE OR REPLACE PROCEDURE get_discounted_product(prod_id INT ,discount_rate NUMERIC)
AS $$
BEGIN

    UPDATE product SET price = price - (price * discount_rate)
    WHERE product_id = prod_id;

END;
$$ LANGUAGE plpgsql;

call get_discounted_product(21, 0.1);

  -- UPDATE product SET price = 100
  --   WHERE product_id = 21;

----write a procedure that takes prod_id and discounted price as input as array
-- and apply discounted price in all given prod ids
CREATE OR REPLACE PROCEDURE get_discounted_product_array(prod_id INT[] ,discount_rate NUMERIC)
AS $$
BEGIN

    UPDATE product SET price = price - (price * discount_rate)
    WHERE product_id = ANY(prod_id);

END;
$$ LANGUAGE plpgsql;
call get_discounted_product_array(ARRAY[21,10,15] , 0.1);


CREATE TABLE accounts (
id SERIAL PRIMARY KEY,
name varchar(100),
balance NUMERIC
);

CREATE TABLE account_audit (
account_id INT,
old_balance NUMERIC,
new_balance NUMERIC,
changed_on TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


--Trigger function 
create or replace function log_trigger_function()
returns trigger
as $$
begin 
insert into account_audit (account_id,old_balance,new_balance)
values (old.id,old.balance,new.balance);
 return new;
 end;
 $$ language plpgsql;


 --trigger
 create trigger balance_update_trigger
 after update on accounts
 for each row 
 when(old.balance is distinct from new.balance)
 execute function log_trigger_function();


